sp_widget.client_script:
api.controller = function($scope) {
    var c = this;

    c.viewTask = function(taskId) {
        var url = '/event_management?id=task_details&sys_id=' + taskId;
        window.location.href = url;
    };

    c.editTask = function(taskId) {
        var url = '/event_management?sys_id=' + taskId+'&view=sp&id=form&table=x_1790227_event_ma_event_task';
        window.location.href = url;
    };

    c.deleteTask = function(taskId) {
        if(confirm('Are you sure you want to delete this task?')) {
            alert('Delete logic for Task ID: ' + taskId);
        }
    };
};

sp_widget.css:
.hc-widget {
    border-radius: 8px;
    box-shadow: 0 2px 6px rgba(0,0,0,0.05);
    font-family: 'Poppins', sans-serif;
    margin-bottom: 20px;
}

.hc-widget .panel-heading {
    background-color: #6A0DAD; /* Lavender/Wine Color */
    color: #fff;
    padding: 12px 20px;
    border-radius: 8px 8px 0 0;
}

.hc-widget .panel-title {
    font-size: 16px;
    font-weight: 600;
}

.table-hover tbody tr:hover {
    background-color: #f2e6ff;
}

sp_widget.script:
(function() {
    data.tasks = [];
    var gr = new GlideRecord('x_1790227_event_ma_event_task');  
    gr.addQuery('active', true);
    gr.orderByDesc('u_due_date');
    gr.query();

    while (gr.next()) {
        data.tasks.push({
            sys_id: gr.getUniqueValue(),
            task_name: gr.getValue('u_task_name'),
            event_name: gr.getDisplayValue('u_event_id'),
            assigned_to: gr.getDisplayValue('u_assigned_to'),
            due_date: gr.getDisplayValue('u_due_date'),
            status: gr.getDisplayValue('u_status')
        });
    }
})();
